contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount is the Ether to attempt to deposit into c via addToBalance
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // observe pre-call values
        uint256 beforeUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBal = address(c).balance;

        // perform the state-changing call and catch revert
        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe post-call values
        uint256 afterUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBal = address(c).balance;

        // General invariant:
        // - If the call reverted: no guarantees about balances inside c, so we allow revert.
        // - If it did not revert: the user's recorded balance must be >= its previous value,
        //   and the contract's on-chain balance must have increased by at least the amount sent.
        // This captures that successful deposits cannot decrease the recorded per-user balance
        // and that Ether sent was received by the contract.
        assert(reverted || (afterUserBal >= beforeUserBal && afterContractBal >= beforeContractBal + amount));
    }

    receive() external payable {}
}

